'use client';

import { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { 
  ArrowRight, MapPin, Clock, Calendar, Bus, 
  User, CheckCircle2, Armchair, CarFront, AlertCircle, Loader2,
  Gauge, Wifi, Coffee, Snowflake, Tv, Shield, Star
} from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { Alert, AlertDescription } from '@/components/ui/alert';

interface Seat {
  id: number;
  seat_number: number;
  is_reserved: boolean;
  reserved_by?: { first_name: string; last_name: string };
}

interface TripDetails {
  id: number;
  route: {
    origin: string;
    destination: string;
    company: string;
    distance_km: number;
    estimated_duration: string;
  };
  fleet: {
    license_plate: string;
    model: string;
    brand: string;
    capacity: number;
    bus_type: "standard" | "vip" | "luxury";
    facilities: string[];
  };
  departure_datetime: string;
  arrival_datetime: string;
  current_price: string;
  status: string;
  driver_name: number;
  driver_phone: string;
}

export default function BookingPage() {
  const params = useParams();
  const router = useRouter();
  const tripId = params.tripId as string;

  const [seats, setSeats] = useState<Seat[]>([]);
  const [tripDetails, setTripDetails] = useState<TripDetails | null>(null);
  const [selectedSeats, setSelectedSeats] = useState<number[]>([]);
  const [loading, setLoading] = useState(true);
  const [reserving, setReserving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const formatPrice = (price: string | number) => Number(price).toLocaleString('fa-IR');
  
  const formatDateTime = (dateString: string) => {
    const date = new Date(dateString);
    return {
      time: date.toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit', hour12: false }),
      date: date.toLocaleDateString('fa-IR', { month: 'long', day: 'numeric' })
    };
  };

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const tripRes = await fetch(`/trips/api/v1/trips/${tripId}/`);
        if (!tripRes.ok) throw new Error('خطا در دریافت اطلاعات سفر');
        const tripData = await tripRes.json();
        setTripDetails(tripData);

        const token = localStorage.getItem('accessToken');
        const seatRes = await fetch(`/seat/api/v1/api/seats/trip/${tripId}/`, {
          headers: token ? { 'Authorization': `Bearer ${token}` } : {}
        });
        if (!seatRes.ok) throw new Error('خطا در دریافت لیست صندلی‌ها');
        const seatData = await seatRes.json();
        setSeats(seatData.seats); 
      } catch (err) {
        console.error(err);
        setError('مشکلی در ارتباط با سرور پیش آمده است. لطفاً مجدداً تلاش کنید.');
      } finally {
        setLoading(false);
      }
    };

    if (tripId) fetchData();
  }, [tripId]);

  const toggleSeat = (seatId: number, isReserved: boolean) => {
    if (isReserved) return;

    setSelectedSeats(prev => {
      if (prev.includes(seatId)) {
        return prev.filter(id => id !== seatId);
      } else {
        if (prev.length >= 4) {
          alert("شما حداکثر می‌توانید ۴ صندلی انتخاب کنید.");
          return prev;
        }
        return [...prev, seatId];
      }
    });
  };

  const handleReservation = async () => {
    if (selectedSeats.length === 0) return;
    
    setReserving(true);
    const token = localStorage.getItem("accessToken");

    try {
      const createRes = await fetch("/reservations/api/v1/api/reservations/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`,
        },
        body: JSON.stringify({ seat: selectedSeats[0] }),
      });

      const reservation = await createRes.json();

      if (!createRes.ok) {
        setError(reservation.detail || reservation.error || "خطا در ایجاد رزرو");
        setReserving(false);
        return;
      }

      const reservationId = reservation.id;

      const payRes = await fetch(
        `/reservations/api/v1/api/reservations/${reservationId}/confirm_payment/`,
        {
          method: "POST",
          headers: { "Authorization": `Bearer ${token}` },
        }
      );

      const payData = await payRes.json();

      if (!payRes.ok) {
        setError(payData.detail || payData.error || "خطا در تایید پرداخت");
        setReserving(false);
        return;
      }

      alert("پرداخت با موفقیت تایید شد!");
      router.push("/dashboard/tickets");
    } catch (err) {
      setError("خطا در پردازش درخواست");
    } finally {
      setReserving(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gradient-to-br from-blue-50 via-sky-50 to-cyan-50 gap-4">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
          <Bus className="w-8 h-8 text-blue-600 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
        </div>
        <p className="text-gray-600 font-medium text-lg">در حال بارگذاری اطلاعات سفر...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-sky-50 to-cyan-50 pb-10 font-sans" dir="rtl">
      
      {/* Header */}
      <header className="bg-white/80 backdrop-blur-lg border-b border-blue-100 sticky top-0 z-50 shadow-sm">
        <div className="container mx-auto px-4 h-16 flex items-center justify-between max-w-7xl">
          <div className="flex items-center gap-4">
            <Button 
              variant="ghost" 
              size="icon" 
              onClick={() => router.back()}
              className="hover:bg-blue-50 rounded-full"
            >
              <ArrowRight className="w-5 h-5 text-blue-600" />
            </Button>
            <div>
              <h1 className="font-bold text-xl text-gray-800">انتخاب صندلی</h1>
              <p className="text-xs text-gray-500">رزرو آنلاین بلیط اتوبوس</p>
            </div>
          </div>
          <div className="hidden sm:flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-full">
            <Shield className="w-4 h-4 text-blue-600" />
            <span className="text-sm text-blue-700 font-medium">خرید امن</span>
          </div>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8 max-w-7xl space-y-8">
        
        {/* Error Alert */}
        {error && (
          <Alert variant="destructive" className="bg-red-50 border-red-200 animate-in slide-in-from-top">
            <AlertCircle className="h-5 w-5" />
            <AlertDescription className="font-medium">{error}</AlertDescription>
          </Alert>
        )}

        {/* Ticket-Style Trip Info */}
        {tripDetails && (
          <div className="relative">
            {/* کارت بلیط با طراحی واقعی */}
            <div className="relative bg-gradient-to-r from-blue-500 via-blue-600 to-cyan-600 rounded-3xl shadow-2xl overflow-hidden">
              {/* طرح پس‌زمینه */}
              <div className="absolute inset-0 opacity-10">
                <div className="absolute top-0 left-0 w-64 h-64 bg-white rounded-full blur-3xl"></div>
                <div className="absolute bottom-0 right-0 w-96 h-96 bg-cyan-300 rounded-full blur-3xl"></div>
              </div>

              {/* محتوای بلیط */}
              <div className="relative p-8">
                {/* Header بلیط */}
                <div className="flex justify-between items-start mb-6">
                  <div>
                    <div className="flex items-center gap-3 mb-2">
                      <div className="bg-white/20 backdrop-blur-sm p-2 rounded-xl">
                        <Bus className="w-6 h-6 text-white" />
                      </div>
                      <div>
                        <h2 className="text-white font-bold text-2xl">{tripDetails.route.company}</h2>
                        <p className="text-blue-100 text-sm">خدمات سفر راحت</p>
                      </div>
                    </div>
                  </div>
                  <div className="flex flex-col gap-2">
                    <Badge className="bg-white/20 text-white border-white/30 hover:bg-white/30 backdrop-blur-sm px-4 py-1.5">
                      {tripDetails.fleet.bus_type === 'vip' ? '⭐ VIP' : '🚌 معمولی'}
                    </Badge>
                    <div className="flex gap-1">
                      <Star className="w-4 h-4 text-yellow-300 fill-yellow-300" />
                      <Star className="w-4 h-4 text-yellow-300 fill-yellow-300" />
                      <Star className="w-4 h-4 text-yellow-300 fill-yellow-300" />
                      <Star className="w-4 h-4 text-yellow-300 fill-yellow-300" />
                      <Star className="w-4 h-4 text-yellow-300 fill-yellow-300" />
                    </div>
                  </div>
                </div>

                {/* مسیر سفر */}
                <div className="bg-white/10 backdrop-blur-md rounded-2xl p-6 border border-white/20">
                  <div className="flex items-center justify-between gap-4">
                    {/* مبدا */}
                    <div className="flex-1 text-center">
                      <div className="bg-white/20 backdrop-blur-sm rounded-xl p-4 mb-3">
                        <MapPin className="w-6 h-6 text-white mx-auto mb-2" />
                        <p className="text-white/80 text-sm mb-1">مبدا</p>
                        <h3 className="text-white font-bold text-2xl">{tripDetails.route.origin}</h3>
                      </div>
                      <div className="text-white font-bold text-3xl mb-1">
                        {formatDateTime(tripDetails.departure_datetime).time}
                      </div>
                      <p className="text-blue-100 text-sm">{formatDateTime(tripDetails.departure_datetime).date}</p>
                    </div>

                    {/* مسیر */}
                    <div className="flex-1 flex flex-col items-center py-4">
                      <div className="relative w-full">
                        <div className="flex items-center justify-center gap-2 mb-3">
                          <div className="bg-white/20 backdrop-blur-sm rounded-full px-4 py-2">
                            <div className="flex items-center gap-2 text-white text-sm">
                              <Clock className="w-4 h-4" />
                              <span className="font-medium">{tripDetails.route.estimated_duration}</span>
                            </div>
                          </div>
                        </div>
                        <div className="relative flex items-center">
                          <div className="h-1 flex-1 bg-white/30 rounded-full overflow-hidden">
                            <div className="h-full w-full bg-gradient-to-r from-white via-cyan-200 to-white animate-pulse"></div>
                          </div>
                          <Bus className="w-8 h-8 text-white mx-4 animate-bounce" style={{animationDuration: '3s'}} />
                          <div className="h-1 flex-1 bg-white/30 rounded-full"></div>
                        </div>
                        <div className="text-center mt-3">
                          <span className="bg-white/20 backdrop-blur-sm text-white text-xs px-3 py-1 rounded-full">
                            {tripDetails.route.distance_km} کیلومتر
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* مقصد */}
                    <div className="flex-1 text-center">
                      <div className="bg-white/20 backdrop-blur-sm rounded-xl p-4 mb-3">
                        <MapPin className="w-6 h-6 text-white mx-auto mb-2" />
                        <p className="text-white/80 text-sm mb-1">مقصد</p>
                        <h3 className="text-white font-bold text-2xl">{tripDetails.route.destination}</h3>
                      </div>
                      <div className="text-white font-bold text-3xl mb-1">
                        {formatDateTime(tripDetails.arrival_datetime).time}
                      </div>
                      <p className="text-blue-100 text-sm">{formatDateTime(tripDetails.arrival_datetime).date}</p>
                    </div>
                  </div>
                </div>

                {/* امکانات */}
                <div className="mt-6 flex flex-wrap gap-3 justify-center">
                  {[
                    { icon: Wifi, label: 'وای‌فای رایگان' },
                    { icon: Coffee, label: 'سرویس چای' },
                    { icon: Snowflake, label: 'تهویه مطبوع' },
                    { icon: Tv, label: 'سرگرمی' }
                  ].map((item, idx) => (
                    <div key={idx} className="flex items-center gap-2 bg-white/10 backdrop-blur-sm px-4 py-2 rounded-full border border-white/20">
                      <item.icon className="w-4 h-4 text-white" />
                      <span className="text-white text-sm font-medium">{item.label}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Ticket Perforation Effect */}
              <div className="absolute left-0 top-1/2 -translate-y-1/2 w-8 h-8 bg-gradient-to-br from-blue-50 via-sky-50 to-cyan-50 rounded-full -ml-4"></div>
              <div className="absolute right-0 top-1/2 -translate-y-1/2 w-8 h-8 bg-gradient-to-br from-blue-50 via-sky-50 to-cyan-50 rounded-full -mr-4"></div>
            </div>
          </div>
        )}

        {/* نقشه صندلی و فاکتور */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          
          {/* نقشه صندلی */}
          <div className="lg:col-span-7">
            <Card className="border-0 shadow-xl bg-white/90 backdrop-blur-sm overflow-hidden">
              <CardHeader className="bg-gradient-to-r from-blue-500 to-cyan-500 text-white pb-6">
                <CardTitle className="text-xl font-bold flex items-center gap-3">
                  <div className="bg-white/20 backdrop-blur-sm p-2 rounded-xl">
                    <Armchair className="w-6 h-6" />
                  </div>
                  <span>انتخاب صندلی مورد نظر</span>
                </CardTitle>
                
                <div className="flex gap-6 pt-4 text-sm">
                  {[
                    { color: 'bg-white', border: 'border-2 border-white', label: 'آزاد' },
                    { color: 'bg-gradient-to-br from-blue-500 to-cyan-500', border: '', label: 'انتخاب شما' },
                    { color: 'bg-gray-300', border: '', label: 'رزرو شده' }
                  ].map((item, idx) => (
                    <div key={idx} className="flex items-center gap-2">
                      <div className={`w-5 h-5 rounded-lg ${item.color} ${item.border} shadow-sm`}></div>
                      <span className="text-white/90">{item.label}</span>
                    </div>
                  ))}
                </div>
              </CardHeader>

              <CardContent className="p-10 flex justify-center">
                {/* اتوبوس کارتونی */}
                <div className="relative">
                  {/* بدنه اتوبوس */}
                  <div className="relative bg-gradient-to-b from-gray-50 to-gray-100 border-4 border-gray-300 rounded-[3rem] rounded-b-2xl p-8 pt-20 pb-16 w-full max-w-[380px] shadow-2xl">
                    
                    {/* شیشه جلو */}
                    <div className="absolute top-4 left-1/2 -translate-x-1/2 w-32 h-16 bg-gradient-to-b from-cyan-200 to-blue-300 rounded-t-3xl border-4 border-gray-300"></div>
                    
                    {/* فرمان */}
                    <div className="absolute top-12 right-12 bg-gray-700 p-3 rounded-full shadow-lg">
                      <Gauge className="w-7 h-7 text-blue-400" />
                    </div>
                    
                    {/* خط تقسیم */}
                    <div className="border-t-2 border-dashed border-blue-300 w-full mb-10 relative">
                      <span className="absolute -top-3 left-1/2 -translate-x-1/2 bg-gradient-to-r from-blue-500 to-cyan-500 text-white px-4 py-1 rounded-full text-xs font-bold shadow-md">
                        جلوی اتوبوس
                      </span>
                    </div>

                    {/* صندلی‌ها */}
                    <div className="grid grid-cols-4 gap-4" dir="ltr">
                      {seats.map((seat) => {
                        const isSelected = selectedSeats.includes(seat.id);
                        const isReserved = seat.is_reserved;

                        return (
                          <div
                            key={seat.id}
                            onClick={() => toggleSeat(seat.id, isReserved)}
                            className={`
                              relative h-14 rounded-xl flex items-center justify-center font-bold text-base transition-all duration-300 cursor-pointer select-none
                              ${isReserved 
                                ? "bg-gray-300 text-gray-500 cursor-not-allowed shadow-inner" 
                                : isSelected 
                                  ? "bg-gradient-to-br from-blue-500 to-cyan-500 text-white shadow-2xl shadow-blue-300 transform -translate-y-2 scale-105" 
                                  : "bg-white text-gray-700 border-2 border-gray-300 hover:border-blue-400 hover:shadow-lg hover:scale-105 shadow-md"
                              }
                            `}
                          >
                            {seat.seat_number}
                            {isSelected && (
                              <div className="absolute -top-2 -right-2 bg-gradient-to-br from-green-400 to-emerald-500 rounded-full p-1 border-3 border-white shadow-lg animate-pulse">
                                <CheckCircle2 className="w-4 h-4 text-white" />
                              </div>
                            )}
                            {isReserved && (
                              <div className="absolute inset-0 flex items-center justify-center">
                                <div className="w-8 h-0.5 bg-gray-500 rotate-45"></div>
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                    
                    {/* خط پایین */}
                    <div className="border-t-2 border-dashed border-blue-300 w-full mt-12 relative">
                      <span className="absolute -top-3 left-1/2 -translate-x-1/2 bg-gradient-to-r from-blue-500 to-cyan-500 text-white px-4 py-1 rounded-full text-xs font-bold shadow-md">
                        عقب اتوبوس
                      </span>
                    </div>

                    {/* چرخ‌ها */}
                    <div className="absolute -bottom-6 left-8 w-12 h-12 bg-gray-800 rounded-full border-4 border-gray-600 shadow-xl"></div>
                    <div className="absolute -bottom-6 right-8 w-12 h-12 bg-gray-800 rounded-full border-4 border-gray-600 shadow-xl"></div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* فاکتور - طرح بلیط */}
          <div className="lg:col-span-5">
            <div className="sticky top-24">
              <div className="relative">
                {/* کارت فاکتور به شکل بلیط */}
                <div className="relative bg-gradient-to-br from-blue-500 via-blue-600 to-cyan-600 rounded-3xl shadow-2xl overflow-hidden">
                  {/* Decorative Background */}
                  <div className="absolute inset-0 opacity-10">
                    <div className="absolute top-0 right-0 w-40 h-40 bg-white rounded-full blur-3xl"></div>
                    <div className="absolute bottom-0 left-0 w-60 h-60 bg-cyan-300 rounded-full blur-3xl"></div>
                  </div>

                  {/* محتوای بلیط */}
                  <div className="relative p-6">
                    {/* Header */}
                    <div className="flex items-center justify-between mb-6">
                      <h3 className="text-white font-bold text-2xl flex items-center gap-2">
                        <div className="bg-white/20 backdrop-blur-sm p-2 rounded-xl">
                          🎫
                        </div>
                        صورتحساب شما
                      </h3>
                      <Badge className="bg-white/20 text-white border-white/30 backdrop-blur-sm">
                        {selectedSeats.length}/4
                      </Badge>
                    </div>

                    {/* صندلی‌های انتخابی */}
                    <div className="bg-white/10 backdrop-blur-md rounded-2xl p-5 mb-5 border border-white/20">
                      {selectedSeats.length > 0 ? (
                        <div className="space-y-3">
                          <p className="text-white/80 text-sm mb-3">صندلی‌های انتخاب شده:</p>
                          <div className="flex flex-wrap gap-2">
                            {seats
                              .filter(s => selectedSeats.includes(s.id))
                              .map(s => (
                                <div key={s.id} className="bg-white/20 backdrop-blur-sm text-white px-4 py-2 rounded-xl font-bold flex items-center gap-2 border border-white/30">
                                  <Armchair className="w-4 h-4" />
                                  <span>صندلی {s.seat_number}</span>
                                </div>
                              ))}
                          </div>
                        </div>
                      ) : (
                        <div className="text-center py-8">
                          <Armchair className="w-12 h-12 text-white/40 mx-auto mb-3" />
                          <p className="text-white/60 text-sm">هنوز صندلی انتخاب نکرده‌اید</p>
                        </div>
                      )}
                    </div>

                    {/* جزئیات قیمت */}
                    <div className="bg-white/10 backdrop-blur-md rounded-2xl p-5 mb-5 space-y-3 border border-white/20">
                      <div className="flex justify-between text-white/80">
                        <span>تعداد صندلی:</span>
                        <span className="font-bold text-white">{selectedSeats.length} عدد</span>
                      </div>
                      <div className="flex justify-between text-white/80">
                        <span>قیمت هر صندلی:</span>
                        <span className="font-bold text-white">
                          {tripDetails ? formatPrice(tripDetails.current_price) : 0} تومان
                        </span>
                      </div>
                      <div className="border-t border-white/20 pt-3 mt-3">
                        <div className="flex justify-between items-center">
                          <span className="text-white font-bold text-lg">مبلغ کل:</span>
                          <div className="text-left">
                            <span className="block font-bold text-3xl text-white">
                              {tripDetails ? formatPrice(selectedSeats.length * Number(tripDetails.current_price)) : 0}
                            </span>
                            <span className="text-white/60 text-sm">تومان</span>
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* دکمه پرداخت */}
                    <Button 
                      className="w-full h-14 text-lg font-bold bg-white text-blue-600 hover:bg-blue-50 shadow-xl hover:shadow-2xl transition-all duration-300 rounded-xl" 
                      onClick={handleReservation}
                      disabled={reserving || selectedSeats.length === 0}
                    >
                      {reserving ? (
                        <div className="flex items-center gap-3">
                          <Loader2 className="w-6 h-6 animate-spin" />
                          <span>در حال پردازش...</span>
                        </div>
                      ) : (
                        <div className="flex items-center gap-3">
                          <CheckCircle2 className="w-6 h-6" />
                          <span>تایید و پرداخت امن</span>
                        </div>
                      )}
                    </Button>

                    {/* یادآوری */}
                    <div className="mt-4 flex items-start gap-2 text-white/60 text-xs bg-white/5 backdrop-blur-sm p-3 rounded-xl border border-white/10">
                      <Shield className="w-4 h-4 shrink-0 mt-0.5" />
                      <p>با کلیک بر روی دکمه پرداخت، قوانین و مقررات خرید بلیط را می‌پذیرم.</p>
                    </div>
                  </div>

                  {/* Ticket Perforation */}
                  <div className="absolute left-0 top-1/2 -translate-y-1/2 w-6 h-6 bg-gradient-to-br from-blue-50 via-sky-50 to-cyan-50 rounded-full -ml-3"></div>
                  <div className="absolute right-0 top-1/2 -translate-y-1/2 w-6 h-6 bg-gradient-to-br from-blue-50 via-sky-50 to-cyan-50 rounded-full -mr-3"></div>
                </div>
              </div>
            </div>
          </div>

        </div>
      </main>
    </div>
  );
}